package dev.gamersclt.batcaverna.nativeapp;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class LibraryQueryTest {
 private JSONArray fixture()throws Exception{return new JSONArray(new String(Files.readAllBytes(Paths.get(System.getProperty("library.fixture"))),java.nio.charset.StandardCharsets.UTF_8));}
 private List<JSONObject> rows(JSONArray source)throws Exception{List<JSONObject> rows=new ArrayList<>();for(int i=0;i<source.length();i++)rows.add(source.getJSONObject(i));return rows;}
 @Test public void wordsAndFiltersMatchTheSharedDesktopFixture()throws Exception{JSONArray data=fixture();List<String> ids=new ArrayList<>();for(JSONObject row:rows(data))if(LibraryQuery.matches(row,"ecarlate POKEMON","acao","PC"))ids.add(row.getString("id"));assertEquals(Arrays.asList("1"),ids);assertTrue(LibraryQuery.matches(data.getJSONObject(3),"serie","Ação","Prime Video"));assertFalse(LibraryQuery.matches(data.getJSONObject(4),"","RPG",""));assertFalse(LibraryQuery.matches(data.getJSONObject(3),"","","PC"));}
 @Test public void ordersMatchDesktopIncludingRatingLabelsAndMilliseconds()throws Exception{JSONArray data=fixture();String before=data.toString();String[] orders={"rating","hours","recent","name"};String[][] expected={{"1","3","4","2","5"},{"3","2","1","5","4"},{"4","2","1","3","5"},{"5","2","1","4","3"}};for(int i=0;i<orders.length;i++){List<JSONObject> rows=rows(data);Collections.sort(rows,LibraryQuery.comparator(orders[i]));List<String> ids=new ArrayList<>();for(JSONObject row:rows)ids.add(row.getString("id"));assertEquals(orders[i],Arrays.asList(expected[i]),ids);}assertEquals(before,data.toString());}
 @Test public void choicesSplitMultiplePlatformsAndKeepAnActiveMissingFilter()throws Exception{assertEquals(Arrays.asList("Netflix","PC","Prime Video","Switch"),LibraryQuery.choices(fixture(),false,""));assertTrue(LibraryQuery.choices(fixture(),true,"Estratégia").contains("Estratégia"));assertEquals(7,LibraryQuery.rating("⭐⭐⭐½ Bom"),0);assertEquals(9,LibraryQuery.rating("4,5/5"),0);}
 @Test public void preparedFiltersInvalidateMutableGenresTitlesAndMediaPlatforms()throws Exception{JSONObject row=new JSONObject().put("nome","Jogo antigo").put("generos",new JSONArray().put("Ação")).put("plataforma","PC").put("categoria","jogos");LibraryQuery.Filter before=LibraryQuery.filter("antigo","acao","PC");assertTrue(before.matches(row));row.put("nome","Jogo novo");assertFalse(before.matches(row));LibraryQuery.Filter after=LibraryQuery.filter("novo","acao","");assertTrue(after.matches(row));row.getJSONArray("generos").put(0,"RPG");assertFalse(after.matches(row));row.put("categoria","filmes").put("onde","Prime Video");assertTrue(LibraryQuery.filter("","","Prime Video").matches(row));assertFalse(LibraryQuery.filter("","","PC").matches(row));}
 @Test public void cachedOrderingInvalidatesChangedDatesRatingsHoursAndNames()throws Exception{JSONObject a=item("Árvore","2020",1).put("id","a").put("horas",10).put("nota","⭐⭐⭐ Ok").put("updated_at","2026-01-01T00:00:00.100Z"),b=item("Bola","2020",2).put("id","b").put("horas",2).put("nota","⭐⭐⭐⭐ Muito bom").put("updated_at","2026-01-01T00:00:00.200Z");assertTrue(LibraryQuery.comparator("recent").compare(a,b)>0);a.put("updated_at","2026-01-01T00:00:00.300Z");assertTrue(LibraryQuery.comparator("recent").compare(a,b)<0);assertTrue(LibraryQuery.comparator("rating").compare(a,b)>0);a.put("nota","💎 Lenda (GOTY)");assertTrue(LibraryQuery.comparator("rating").compare(a,b)<0);assertTrue(LibraryQuery.comparator("hours").compare(a,b)<0);b.put("horas",20);assertTrue(LibraryQuery.comparator("hours").compare(a,b)>0);a.put("nome","Zebra");assertTrue(LibraryQuery.comparator("name").compare(a,b)>0);}
 private JSONObject item(String name,String year,long steam)throws Exception{return new JSONObject().put("nome",name).put("ano",year).put("steam_appid",steam);}

}
